export function renderLabels(lang='EN'){return {renderReusedResult:lang==='HU'?'Korábbi kész eredmény újrahasználva — az eredeti mappájában maradt, nem generálta újra. A pontos helye és letöltése lent látható.':'Reused completed result — kept in its original folder, not generated again. Its exact location and download are below.',renderSeveralFolders:lang==='HU'?'A kész videók több mappában vannak. A korábbról újrahasznált snittek az eredeti helyükön maradnak; minden kártyán megtalálod a pontos útvonalat és a letöltést.':'Completed videos span multiple folders. Reused shots remain in their original locations; each card shows its exact path and download.',monitorOtherWork:lang==='HU'?'Másik futó ComfyUI-feladat':'Other running ComfyUI jobs',monitorFinalVideo:lang==='HU'?'Elkészült videó':'Finished video',monitorRestart:lang==='HU'?'Az élő futásnézethez indítsd újra a Scene DNA saját helyi szerverét a megszokott indítóval, majd Ctrl+F5. A SwarmUI-t nem kell újraindítani.':'Restart the Scene DNA local server with its usual launcher, then Ctrl+F5 to enable the live monitor. SwarmUI does not need restarting.',monitorWaiting:lang==='HU'?'Indításra / a ComfyUI sorára vár':'Waiting to submit / for the ComfyUI queue',...(monitorLabels[lang]||monitorLabels.EN),...(orientationLabels[lang]||orientationLabels.EN),...(renderErrorLabels[lang]||renderErrorLabels.EN),...Object.fromEntries(renderPromptKeys.map((k,i)=>[k,(renderPromptTables[lang]||renderPromptTables.EN)[i]])),...Object.fromEntries(renderKeys.map((k,i)=>[k,(renderTables[lang]||renderTables.EN).split('|')[i]])),privacy:renderPrivacy[lang]||renderPrivacy.EN};}
export function validateRenderLabels(){return Object.values(renderPromptTables).every(v=>v.length===renderPromptKeys.length)&&Object.values(renderTables).every(v=>v.split('|').length===renderKeys.length);}
